import {DawgAtelier} from './dawg-atelier.js';
import {flexRating} from './dawg-fashion.js';
import {ATTRIBUTES,DISCIPLINES,DAWG_LIMIT,baseTraits,makeDawg,makeKennel,validKennel,adopt,levelOf,xpAtLevel,statsOf,pointsOf,train,ratingOf,rankOf,league,bindSession,finishSession,characterFile,parseCharacter,benefits} from './dawg-career.js';
import {drawDawg,drawCharacterCard,traitLabels} from './dawg-art.js';
const $=id=>document.getElementById(id);
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
function picture(d,w=240,h=300){const canvas=node('canvas');canvas.width=w*2;canvas.height=h*2;canvas.setAttribute('role','img');canvas.setAttribute('aria-label',d.name+', a full-body '+traitLabels(d).map(t=>t[1]).join(', ')+' DAWG');const c=canvas.getContext('2d');c.scale(2,2);drawDawg(c,d,w/2,h/2,h*.94);return canvas;}
function download(blob,name){const url=URL.createObjectURL(blob),a=node('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export class DawgKennel {
 constructor(io){this.io=io;const saved=io.read('kennel',null);this.state=validKennel(saved)?saved:makeKennel();this.candidate=null;this.tab='home';this.save();this.studio=new DawgAtelier({dawg:()=>this.active,save:()=>{this.save();this.render();this.io.appearanceChanged?.();},notice:text=>this.notice(text)});
  $('kennelButton').onclick=()=>this.open('home');$('leagueButton').onclick=()=>this.open('league');$('discoverDawg').onclick=()=>this.discover();$('rerollDawg').onclick=()=>this.discover();$('adoptDawg').onclick=()=>{if(!this.candidate)return;try{const d=adopt(this.state,this.candidate);const name=$('candidateName').value?.trim();if(name&&name.length<=28&&!/[\u0000-\u001f<>]/.test(name))d.name=name;this.candidate=null;this.save();this.selectTab('home');this.render();this.notice(d.name+' joined your kennel. New runs will use this DAWG.');}catch(e){this.notice(e.message);}};
  $('kennelTabs').onclick=e=>{const b=e.target.closest('[data-kennel-tab]');if(b)this.selectTab(b.dataset.kennelTab);};
  $('kennelRoster').onclick=e=>{const b=e.target.closest('[data-dawg]');if(!b)return;this.state.activeId=b.dataset.dawg;this.save();this.render();this.notice(this.active.name+' is ready for your next fresh run. Paused runs keep their original DAWG.');};
  $('dawgTraining').onclick=e=>{const b=e.target.closest('[data-train]');if(b&&train(this.active,b.dataset.train)){this.save();this.render();this.notice('Training saved. Benefits apply to new runs; Daily Run keeps standard rules.');}};
  $('renameDawg').onclick=()=>{const name=$('dawgNameInput').value?.trim();if(!name||name.length>28||/[\u0000-\u001f<>]/.test(name)){this.notice('Use 1–28 characters without angle brackets or control characters.');return;}this.active.name=name;this.save();this.render();this.notice('Name updated. DNA stays the same.');};
  $('exportDawg').onclick=()=>{download(new Blob([JSON.stringify(characterFile(this.active),null,2)],{type:'application/json'}),'DAWG-'+this.active.id.slice(0,8)+'.json');this.notice('Character file downloaded. Keep it safe: it contains this DAWG’s identity and growth.');};
  $('portraitDawg').onclick=()=>{const c=node('canvas');c.width=720;c.height=1000;drawCharacterCard(c.getContext('2d'),this.active);c.toBlob(blob=>{if(blob){download(blob,'DAWG-'+this.active.id.slice(0,8)+'.png');this.notice('Collectible portrait downloaded. Use the JSON file or full backup to transfer progress.');}},'image/png');};
  $('importDawg').onclick=()=>{$('dawgFile').value='';$('dawgFile').click();};
  $('dawgFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>50000)throw new Error('Choose a character JSON file smaller than 50 KB.');const d=parseCharacter(await file.text());adopt(this.state,d);this.save();this.selectTab('home');this.render();this.notice(d.name+' imported. Character files copy an identity; they are not exclusive ownership certificates.');}catch(error){this.notice(error.message);}});
  $('leagueSort').addEventListener('change',()=>this.renderLeague());this.render();
 }
 get active(){return this.state.dawgs.find(d=>d.id===this.state.activeId);}
 save(){this.io.write('kennel',this.state);}
 notice(text){$('kennelStatus').textContent=text;}
 open(tab='home'){this.io.open('kennelDialog');this.selectTab(tab);this.render();}
 selectTab(tab){this.tab=['home','discover','league','fashion'].includes(tab)?tab:'home';$('kennelHome').hidden=this.tab!=='home';$('kennelFashion').hidden=this.tab!=='fashion';if(this.tab==='fashion')this.studio.open();else this.studio.hide();$('kennelDiscover').hidden=this.tab!=='discover';$('kennelLeague').hidden=this.tab!=='league';document.querySelectorAll('[data-kennel-tab]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.kennelTab===this.tab)));if(this.tab==='discover'&&!this.candidate)this.discover();if(this.tab==='league')this.renderLeague();}
 discover(){try{this.candidate=makeDawg();this.selectTab('discover');this.renderCandidate();this.notice('A fresh DNA roll. Browse as many as you like; adopt the ones you want to grow.');}catch(e){this.notice(e.message);}}
 renderCandidate(){const d=this.candidate;if(!d)return;$('candidateArt').replaceChildren(picture(d));$('candidateName').value=d.name;$('candidateDNA').textContent=d.id;$('candidateRarity').textContent=baseTraits(d).rarity+' · '+baseTraits(d).affinity+' affinity';this.traits('candidateTraits',d);$('adoptDawg').disabled=this.state.dawgs.length>=DAWG_LIMIT;$('adoptDawg').textContent=this.state.dawgs.length>=DAWG_LIMIT?'KENNEL FULL · 24 / 24':'ADOPT THIS DAWG ↗';}
 traits(id,d){$(id).replaceChildren(...traitLabels(d).map(([label,text])=>{const item=node('div');item.append(node('small',label),node('strong',text));return item;}));}
 characterFor(g){return this.state.dawgs.find(d=>d.id===g?.dawgId)||this.active;}
 prepare(mode,g,force=false){const prior=this.state.sessions[mode]?.id,s=bindSession(this.state,mode,g,force);if(s?.id!==prior)this.save();return this.characterFor(g);}
 record(mode,score,meta={}){const result=finishSession(this.state,mode,Math.round(score),meta);if(!result)return null;this.save();this.render();if(result.xp)this.io.announce(result.dawg.name+' +'+result.xp+' XP'+(result.levels?' · LEVEL '+levelOf(result.dawg)+' · +'+result.levels*2+' TRAINING POINTS':''));return result;}
 render(){const d=this.active,lv=levelOf(d),rating=ratingOf(d),traits=baseTraits(d);$('activeDawgName').textContent=d.name;$('activeDawgInfo').textContent='LEVEL '+lv+' · '+flexRating(d)+' FLEX · '+rating.toLocaleString()+' CP';$('activeDawgArt').replaceChildren(picture(d,126,154));$('activeDawgPoints').textContent=pointsOf(d)+' TRAINING POINT'+(pointsOf(d)===1?'':'S');$('kennelCount').textContent=this.state.dawgs.length+' / '+DAWG_LIMIT+' DAWGS';$('dawgArt').replaceChildren(picture(d));$('dawgNameInput').value=d.name;$('dawgDNA').textContent=d.id;$('dawgRarity').textContent=traits.rarity+' · '+traits.affinity+' affinity';$('dawgLevel').textContent='LEVEL '+lv+' / 50';$('dawgRank').textContent=rankOf(d)+' · '+rating+' / 9000 circuit points';const pct=lv===50?100:(d.xp-xpAtLevel(lv))/(xpAtLevel(lv+1)-xpAtLevel(lv))*100;$('dawgXPFill').style.width=pct+'%';$('dawgXP').textContent=lv===50?'MAX LEVEL · KEEP CHASING CIRCUIT POINTS':(xpAtLevel(lv+1)-d.xp)+' XP TO LEVEL '+(lv+1)+' · +2 TRAINING POINTS';$('dawgPoints').textContent=pointsOf(d)+' POINTS TO SPEND';this.traits('dawgTraits',d);
  $('kennelRoster').replaceChildren(...this.state.dawgs.map(p=>{const b=node('button',undefined,'roster-dawg');b.dataset.dawg=p.id;b.setAttribute('aria-pressed',String(p.id===d.id));b.append(picture(p,68,84),node('strong',p.name),node('small','LV '+levelOf(p)+' · '+ratingOf(p)+' CP'));return b;}));
  const stats=statsOf(d),benefit=benefits(stats);const values={agility:Math.round(benefit.dash*100)+'% quicker dash · +'+benefit.perfect.toFixed(1)+'px perfect zone',focus:'+'+benefit.power.toFixed(1)+'s beast mode · +'+benefit.magnet.toFixed(1)+'s magnet',nerve:'+'+benefit.idle.toFixed(1)+'s Cross idle · +'+Math.round(benefit.thinking*100)+'% Snake time',hustle:'+$'+benefit.cash+' starting cash / new hustle',charm:'+'+Math.round(benefit.order*100)+'% order pay · +'+Math.round(benefit.storyXP*100)+'% story XP',appearance:'Unlock fashion tiers at 5 / 10 / 15 / 20 / 25 · '+flexRating(d)+' FLEX'};
  $('dawgTraining').replaceChildren(...ATTRIBUTES.map(a=>{const row=node('div',undefined,'training-row'),copy=node('div'),bar=node('div',undefined,'gene-meter'),fill=node('i');fill.style.width=(stats[a.id]/25*100)+'%';bar.append(fill);copy.append(node('strong',a.icon+' '+a.name+' '+stats[a.id]+' / 25'),bar,node('small',values[a.id]));const b=node('button',stats[a.id]>=25?'MAX':'+ TRAIN');b.dataset.train=a.id;b.disabled=pointsOf(d)<1||stats[a.id]>=25;b.setAttribute('aria-label','Train '+a.name+', costs 1 point');row.append(copy,b);return row;}));
  $('dawgHistory').replaceChildren(...(d.history.length?d.history.map(h=>node('p',DISCIPLINES.find(m=>m.id===h.mode).name+' · '+h.score.toLocaleString()+' · +'+h.xp+' XP')):[node('p','Your story starts with your next completed run.')]));
  $('dawgEvolution').textContent=lv>=25?'SIGNATURE EVOLUTION · crest stars unlocked':lv>=10?'AWAKENED · aura unlocked · signature at level 25':'ORIGIN · aura unlocks at level 10 · signature at level 25';this.renderLeague();if(this.tab==='fashion')this.studio.refresh();
 }
 renderLeague(){const sort=$('leagueSort').value||'rating',list=sort==='flex'?[...this.state.dawgs].sort((a,b)=>flexRating(b)-flexRating(a)||a.id.localeCompare(b.id)):league(this.state.dawgs,sort);$('characterLeague').replaceChildren(...list.map((d,i)=>{const row=node('article',undefined,'league-row');row.append(node('b',String(i+1).padStart(2,'0')),picture(d,57,70));const info=node('div');info.append(node('strong',d.name),node('small',rankOf(d)+' · LV '+levelOf(d)+' · '+Object.keys(d.records).length+' / 9 games'));row.append(info,node('strong',sort==='flex'?flexRating(d)+' FLEX':ratingOf(d).toLocaleString()+' CP'));return row;}));const d=this.active;$('leagueBreakdownTitle').textContent=d.name+' / YOUR CIRCUIT';$('leagueBreakdown').replaceChildren(...DISCIPLINES.map(m=>{const best=d.records[m.id],cp=Math.min(1000,Math.floor(Math.max(0,best||0)/m.target*1000)),row=node('div',undefined,'circuit-row'),b=node('button',m.name+' ↗');b.onclick=()=>{$('kennelDialog').close();this.io.play(m.id);};row.append(b,node('span',best===undefined?'UNPLAYED':best.toLocaleString()+' BEST'),node('strong',cp+' / 1000'));return row;}));}
}
